def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate the regularly spaced separator rows and columns by their non-background color.
    bg = max(set(sum(grid, [])), key=lambda c: sum(row.count(c) for row in grid))
    rows = [r for r in range(h) if any(v != bg for v in grid[r])]
    cols = [c for c in range(w) if any(grid[r][c] != bg for r in range(h))]
    # Keep the regularly spaced separator positions.
    def regular_positions(pos):
        if len(pos) < 2:
            return pos
        gaps = [b-a for a, b in zip(pos, pos[1:])]
        step = max(set(gaps), key=gaps.count)
        return [p for p in pos if (p-pos[0]) % step == 0]
    rows, cols = regular_positions(rows), regular_positions(cols)
    out = [[bg for _ in cols] for _ in rows]
    for i, r in enumerate(rows):
        for j, c in enumerate(cols):
            if grid[r][c] != bg:
                out[i][j] = grid[r][c]
    return out
